(window.EXSUB_C=window.EXSUB_C||{})[1]={"k-3":[{"t":"Cooperación pasiva vs. activa (LO 18/2003, arts. 2 y 3)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⇄</i>Cooperación pasiva vs. activa (LO 18/2003, arts. 2 y 3)</div><div class=\"vis-comp med\" style=\"--n:2\"><div class=\"vis-col\"><h5><mark class=\"m-destacable\">PASIVA</mark> · art. 2</h5><ul><li>España <mark class=\"m-accion\">prestará</mark> <mark class=\"m-resp\">plena cooperación</mark> a la <mark class=\"m-autoridad\">Corte</mark></li><li><u class=\"m-clave\">en especial</u>: <mark class=\"m-resp\">art. 86</mark> del Estatuto</li><li>La presta España a la <mark class=\"m-autoridad\">Corte</mark></li></ul></div><div class=\"vis-mid\">⇄</div><div class=\"vis-col\"><h5><mark class=\"m-destacable\">ACTIVA</mark> · art. 3</h5><ul><li><mark class=\"m-autoridad\">Órganos</mark> judiciales y <mark class=\"m-autoridad\">Ministerio Fiscal</mark> <mark class=\"m-accion\">podrán dirigir</mark> solicitudes a la <mark class=\"m-autoridad\">Corte</mark></li><li>Por conducto del <mark class=\"m-resp\">Ministerio de Justicia</mark></li><li>En <mark class=\"m-resp\">un proceso que se siguiere en España</mark> · <mark class=\"m-resp\">art. 93.10</mark> del Estatuto</li></ul></div></div></div>"}],"l-4":[{"t":"Autoridades competentes (LO 18/2003, art. 4)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Autoridades competentes (LO 18/2003, art. 4)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-autoridad\">Autoridades</mark> <mark class=\"m-destacable\">competentes</mark> para aplicar la ley</div><div class=\"vis-ramas\"><div class=\"vis-rama\">a) El <mark class=\"m-resp\">Gobierno</mark></div><div class=\"vis-rama\">b) El <mark class=\"m-resp\">Ministerio de Justicia</mark></div><div class=\"vis-rama\">c) El <mark class=\"m-resp\">Ministerio de Asuntos Exteriores</mark>: <mark class=\"m-resp\">en los casos previstos en esta ley y, en todo caso, cuando intervinieran factores de política exterior</mark></div><div class=\"vis-rama\">d) Defensa e Interior: cuando el acto de cooperación afecte a sus competencias</div><div class=\"vis-rama\">e) <mark class=\"m-autoridad\">Órganos</mark> judiciales de la jurisdicción ordinaria y, en particular, la <mark class=\"m-resp\">Audiencia Nacional</mark></div><div class=\"vis-rama\">f) <mark class=\"m-autoridad\">Órganos</mark> judiciales militares y, en particular, el <mark class=\"m-resp\">Tribunal Militar Central</mark></div><div class=\"vis-rama\">g) El <mark class=\"m-resp\">Ministerio Fiscal</mark></div></div></div></div>"}],"l-5":[{"t":"Representación de España ante la Corte (art. 5)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Representación de España ante la Corte (art. 5)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-destacable\">Representación y defensa en juicio</mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\">Corresponde a los <mark class=\"m-resp\">Abogados del Estado integrados en la Abogacía General del Estado</mark></div><div class=\"vis-rama\">Instrucciones impartidas <mark class=\"m-resp\">conjuntamente</mark> por el <mark class=\"m-resp\">Ministerio de Justicia y el Ministerio de Asuntos Exteriores</mark></div><div class=\"vis-rama\">Si afecta a materias de otro departamento ministerial: <mark class=\"m-accion\">se oirá</mark> a éste antes</div><div class=\"vis-rama\">Excepcional: el <mark class=\"m-autoridad\">Gobierno,</mark> oído el <mark class=\"m-autoridad\">Abogado</mark> General del <mark class=\"m-autoridad\">Estado,</mark> puede nombrar un agente de España, que <mark class=\"m-resp\">asumirá las funciones de Abogado del Estado</mark></div></div></div></div>"}],"l-6":[{"t":"Relación y consulta con la Corte (art. 6)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Relación y consulta con la Corte (art. 6)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-resp\">Ministerio de Justicia</mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\"><mark class=\"m-resp\">Único órgano de relación</mark> entre la <mark class=\"m-autoridad\">Corte</mark> y los <mark class=\"m-autoridad\">órganos</mark> judiciales y el <mark class=\"m-autoridad\">Ministerio Fiscal</mark></div><div class=\"vis-rama\">También <mark class=\"m-autoridad\">órgano</mark> de consulta con la <mark class=\"m-autoridad\">Corte:</mark> informa antes a Exteriores</div><div class=\"vis-rama\">Si afecta a Interior o Defensa: <mark class=\"m-resp\">recabará el informe de estos departamentos</mark></div><div class=\"vis-rama\">Si hay política exterior: <mark class=\"m-resp\">será competente Exteriores, en coordinación con Justicia</mark></div></div></div></div>"}],"l-8":[{"t":"Requerimiento de inhibición (art. 8)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>➜</i>Requerimiento de inhibición (art. 8)</div><div class=\"vis-flujo\"><div class=\"vis-paso \"><span class=\"et\">1</span>El <mark class=\"m-autoridad\">Fiscal</mark> de la <mark class=\"m-autoridad\">Corte</mark> notifica el inicio de una investigación (art. 18.1 del Estatuto) al <mark class=\"m-autoridad\">Ministerio</mark> de Justicia</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">2</span>Justicia pide información urgente al <mark class=\"m-autoridad\">Fiscal</mark> General del <mark class=\"m-autoridad\">Estado</mark> sobre actuaciones penales</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">3</span>Los <mark class=\"m-autoridad\">Ministros</mark> de Justicia y Exteriores elevan propuesta conjunta al <mark class=\"m-autoridad\">Consejo de Ministros</mark> en plazo que <mark class=\"m-accion\">no podrá rebasar</mark> <mark class=\"m-resp\">veinte días</mark></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">4</span>El <mark class=\"m-autoridad\">Consejo de Ministros</mark> resuelve sostener la competencia española y pedir la inhibición (<mark class=\"m-resp\">art. 18.2 del Estatuto</mark>)</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">5</span>Corresponde al <mark class=\"m-resp\">Ministerio de Justicia formular la petición de inhibición</mark></div></div></div>"}],"l-9":[{"t":"Competencia exclusiva del Gobierno (arts. 7 y 9)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⇄</i>Competencia exclusiva del Gobierno (arts. 7 y 9)</div><div class=\"vis-comp\" style=\"--n:2\"><div class=\"vis-col\"><h5>Art. 7 · denunciar una situación</h5><ul><li><u class=\"m-clave\">Exclusivamente</u> el <mark class=\"m-resp\">Gobierno, mediante Acuerdo del Consejo de Ministros</mark></li><li>A propuesta conjunta de Exteriores y Justicia</li><li><mark class=\"m-resp\">Decidir la presentación de la denuncia de una situación ante el Fiscal de la Corte</mark></li><li>Reconsideración: <mark class=\"m-resp\">art. 53.3.a)</mark> del Estatuto</li><li>Hechos en otros <mark class=\"m-autoridad\">Estados</mark> y autores no españoles: <mark class=\"m-resp\">se abstendrán de todo procedimiento</mark> e informan de que pueden acudir al <mark class=\"m-autoridad\">Fiscal</mark> de la <mark class=\"m-autoridad\">Corte</mark></li></ul></div><div class=\"vis-col\"><h5>Art. 9 · impugnar competencia o admisibilidad</h5><ul><li><u class=\"m-clave\">Exclusivamente</u> el <mark class=\"m-resp\">Gobierno, mediante Acuerdo del Consejo de Ministros</mark></li><li>A propuesta conjunta de Justicia y Exteriores</li><li><mark class=\"m-resp\">A la mayor brevedad posible, antes del inicio del juicio en la Corte</mark></li><li>Después del inicio: solo por <mark class=\"m-resp\">haberse producido ya cosa juzgada en España</mark></li></ul></div></div></div>"}],"k-10":[{"t":"Inhibición a favor de la Corte (arts. 8-10)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>➜</i>Inhibición a favor de la Corte (arts. 8-10)</div><div class=\"vis-flujo\"><div class=\"vis-paso \"><span class=\"et\">8</span><mark class=\"m-resp\">Solicitud de inhibición al Fiscal de la Corte (art. 8)</mark></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">9</span><mark class=\"m-resp\">Impugnación de la competencia o admisibilidad (art. 9)</mark></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">=</span>La <mark class=\"m-autoridad\">Sala</mark> competente de la <mark class=\"m-autoridad\">Corte</mark> <mark class=\"m-resp\">autoriza al Fiscal a proceder a la investigación o mantiene su competencia</mark></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso si\"><span class=\"et\">10</span>El <mark class=\"m-autoridad\">órgano</mark> jurisdiccional español <mark class=\"m-resp\">se inhibirá a favor de la Corte y a su solicitud le remitirá lo actuado</mark></div></div></div>"}],"l-12":[{"t":"Libertad provisional del detenido (art. 12)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>➜</i>Libertad provisional del detenido (art. 12)</div><div class=\"vis-flujo\"><div class=\"vis-paso \"><span class=\"et\">1</span>El detenido solicita su libertad provisional</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">2</span>El JCI acuerda remitir la solicitud a la <mark class=\"m-autoridad\">Corte</mark> <mark class=\"m-resp\">a través del Ministerio de Justicia</mark>, con plazo para recibir recomendaciones que <mark class=\"m-resp\">no será inferior a veinte días</mark></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">3</span>Mientras tanto: prisión provisional por el tiempo estrictamente necesario</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">4</span>Recibidas las recomendaciones, el JCI <mark class=\"m-accion\">podrá acordar</mark> la libertad si hay circunstancias urgentes y excepcionales</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">5</span>Si la <mark class=\"m-autoridad\">Corte</mark> no remite la documentación del art. 91 en plazo: libertad provisional y medidas cautelares por un <mark class=\"m-resp\">tiempo máximo de ciento ochenta días</mark></div></div></div>"}],"e-17":[{"t":"Detención y entrega a la Corte (LO 18/2003, arts. 11-17)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>➜</i>Detención y entrega a la Corte (LO 18/2003, arts. 11-17)</div><div class=\"vis-flujo\"><div class=\"vis-paso \"><span class=\"et\">1</span>Detención en cumplimiento de una orden de la <mark class=\"m-autoridad\">Corte</mark> (art. 11)</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">2</span>La <mark class=\"m-autoridad\">autoridad</mark> que detiene lo comunica inmediatamente <mark class=\"m-resp\">al Ministerio de Justicia y al Juez Central de Instrucción de la Audiencia Nacional</mark></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">3</span>A disposición del JCI <mark class=\"m-resp\">sin demora y, en todo caso, dentro del plazo de setenta y dos horas</mark></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">4</span>El JCI oye a la persona reclamada (con letrado e intérprete) y al <mark class=\"m-autoridad\">Fiscal</mark> <mark class=\"m-resp\">dentro de las setenta y dos horas siguientes</mark></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">5</span>Se pregunta si consiente en su entrega (art. 13)</div><div class=\"vis-flecha\">↓</div><div class=\"vis-bifurca\"><div class=\"vis-paso si\"><span class=\"et\">SÍ</span>Auto de entrega <mark class=\"m-resp\">sin más trámites</mark> y sin documentación del art. 91 del Estatuto · consentimiento irrevocable</div><div class=\"vis-paso no\"><span class=\"et\">NO</span><mark class=\"m-autoridad\">Audiencia</mark> <mark class=\"m-resp\">en el plazo máximo de diez días</mark> (art. 15) · el JCI resuelve por auto <mark class=\"m-resp\">en el plazo de tres días</mark></div></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">6</span>Recursos (art. 17): apelación <mark class=\"m-resp\">ante la Sala de lo Penal de la Audiencia Nacional</mark> · situación personal: art. 766 LECrim, auto <mark class=\"m-resp\">en el plazo de cinco días</mark> · los autos de la <mark class=\"m-autoridad\">Sala</mark> <mark class=\"m-resp\">no serán susceptibles de recurso alguno</mark></div></div></div>"}],"l-13":[{"t":"Plazos de la LO 18/2003","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⏱</i>Plazos de la LO 18/2003</div><div class=\"vis-plazos\"><div class=\"vis-plazo\"><span class=\"n\">20 días</span><u class=\"m-clave\">no inferior</u>: plazo para recibir las recomendaciones de la <mark class=\"m-autoridad\">Corte</mark> sobre la libertad provisional (art. 12)</div><div class=\"vis-plazo\"><span class=\"n\">72 h + 72 h</span>Puesta a disposición del JCI y <mark class=\"m-autoridad\">audiencia</mark> de la persona reclamada (art. 11)</div><div class=\"vis-plazo\"><span class=\"n\">15 días</span>Consentimiento posterior a la entrega, aunque se hubiere opuesto (art. 13.3)</div><div class=\"vis-plazo\"><span class=\"n\">10 días</span><mark class=\"m-autoridad\">Audiencia</mark> de entrega: plazo máximo (art. 15.1)</div><div class=\"vis-plazo\"><span class=\"n\">3 días</span>El JCI resuelve por auto sobre la entrega (art. 15.3)</div><div class=\"vis-plazo\"><span class=\"n\">5 días</span>Auto de la <mark class=\"m-autoridad\">Sala</mark> de lo Penal al resolver la apelación sobre situación personal (art. 17.1)</div><div class=\"vis-plazo\"><span class=\"n\">20 días</span>Propuesta conjunta Justicia + Exteriores al <mark class=\"m-autoridad\">Consejo de Ministros</mark> (art. 8.2)</div><div class=\"vis-plazo\"><span class=\"n\">180 días</span>Libertad provisional si la <mark class=\"m-autoridad\">Corte</mark> no remite la documentación (art. 12.3)</div><div class=\"vis-plazo\"><span class=\"n\">24 h</span>Llegada del recluso al <mark class=\"m-autoridad\">juez</mark> de vigilancia penitenciaria (art. 22.1)</div></div></div>"}],"l-16":[{"t":"Solicitudes concurrentes (art. 16)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Solicitudes concurrentes (art. 16)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\">Entrega a la <mark class=\"m-autoridad\">Corte</mark> + extradición u orden europea</div><div class=\"vis-ramas\"><div class=\"vis-rama\">Se notifica a la <mark class=\"m-autoridad\">Corte</mark> y al <mark class=\"m-autoridad\">Estado</mark> requirente</div><div class=\"vis-rama\"><mark class=\"m-resp\">Se tramitan conjuntamente ambos procedimientos en el JCI que conoce de la entrega</mark></div><div class=\"vis-rama\">El JCI se abstiene y eleva ambos procesos a la <mark class=\"m-resp\">Sala de lo Penal de la Audiencia Nacional</mark></div><div class=\"vis-rama\">Sin tratado con el <mark class=\"m-autoridad\">Estado</mark> requirente: <mark class=\"m-resp\">se dará preferencia a la solicitud de la Corte</mark></div></div></div></div>"}],"e-18":[{"t":"Entrega temporal (art. 18)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>➜</i>Entrega temporal (art. 18)</div><div class=\"vis-flujo\"><div class=\"vis-paso \"><span class=\"et\">1</span>Entrega acordada y la persona está <mark class=\"m-resp\">cumpliendo condena en España o sujeta a proceso por hechos distintos</mark></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">2</span>Justicia consulta con la <mark class=\"m-autoridad\">Corte,</mark> <mark class=\"m-resp\">si no se opusiere el Tribunal sentenciador o el instructor</mark></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">3</span>Resolución motivada, con las modalidades de restitución a España · <mark class=\"m-resp\">se computa el período pasado a disposición de la Corte</mark></div></div></div>"},{"t":"Decisiones preliminares sobre admisibilidad (art. 18)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>➜</i>Decisiones preliminares sobre admisibilidad (art. 18)</div><div class=\"vis-flujo\"><div class=\"vis-paso \"><span class=\"et\">1</span>El <mark class=\"m-autoridad\">fiscal</mark> notifica a todos los <mark class=\"m-autoridad\">Estados Partes</mark> y a los <mark class=\"m-autoridad\">Estados</mark> que ejercerían normalmente la jurisdicción</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">2</span>El <mark class=\"m-autoridad\">Estado</mark> informa de que investiga <mark class=\"m-resp\">dentro del mes siguiente</mark> a la notificación</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">3</span>A petición del <mark class=\"m-autoridad\">Estado, el fiscal</mark> se inhibe, <u class=\"m-clave\">a menos que</u> la <mark class=\"m-autoridad\">Sala</mark> de Cuestiones Preliminares, a petición del <mark class=\"m-autoridad\">fiscal,</mark> autorice la investigación</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">4</span>Reexamen: <mark class=\"m-resp\">al cabo de seis meses a partir de la fecha de la inhibición o cuando se haya producido un cambio significativo de circunstancias</mark></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">5</span>Apelación del <mark class=\"m-autoridad\">Estado</mark> o del <mark class=\"m-autoridad\">fiscal</mark> ante la <mark class=\"m-resp\">Sala de Apelaciones</mark> (forma sumaria)</div></div></div>"}],"l-21":[{"t":"Peritos y testigos citados por la Corte (art. 21)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⇄</i>Peritos y testigos citados por la Corte (art. 21)</div><div class=\"vis-comp\" style=\"--n:2\"><div class=\"vis-col\"><h5>Comparecer ante <mark class=\"m-autoridad\">tribunales</mark> españoles <mark class=\"m-autoridad\">(comisión</mark> rogatoria)</h5><ul><li><mark class=\"m-resp\">Mismas obligaciones y responsabilidades que si hubieren sido citadas en una causa en España</mark></li></ul></div><div class=\"vis-col\"><h5>Comparecer en la sede de la <mark class=\"m-autoridad\">Corte</mark></h5><ul><li><mark class=\"m-resp\">Carácter voluntario</mark></li><li>Sin consentimiento: <mark class=\"m-resp\">un condenado por la Corte que cumple condena en España</mark></li><li>Personas en tránsito para comparecer ante la <mark class=\"m-autoridad\">Corte:</mark> <mark class=\"m-destacable\">inmunidad</mark> (art. 21.3)</li></ul></div></div></div>"}],"l-25":[{"t":"Juicio y actuaciones procesales de la Corte en España (arts. 24 y 25)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Juicio y actuaciones procesales de la Corte en España (arts. 24 y 25)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\">Propuesta de la <mark class=\"m-autoridad\">Corte</mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\">Art. 24 · «amicus curiae»<div class=\"vis-sub\"><span><mark class=\"m-resp\">Invitación de la Corte</mark></span><span>Justicia consulta con Exteriores <mark class=\"m-resp\">la conveniencia u oportunidad</mark></span><span>y <mark class=\"m-resp\">fija los términos de dicha participación</mark></span></div></div><div class=\"vis-rama\">Art. 25 · celebrar el juicio en España<div class=\"vis-sub\"><span>Decide y comunica el <mark class=\"m-resp\">Ministerio de Justicia</mark></span><span>Previa consulta con Exteriores, Interior y <mark class=\"m-resp\">otras autoridades competentes</mark></span><span>Aspectos no jurisdiccionales: <mark class=\"m-resp\">acuerdo específico que se celebre con la Corte</mark></span></div></div></div></div></div>"}],"k-datos":[{"t":"Títulos de la Carta (Niza 2000 · vinculante desde el 1-12-2009)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Títulos de la Carta (Niza 2000 · vinculante desde el 1-12-2009)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-destacable\">Carta de Derechos Fundamentales de la UE</mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\"><mark class=\"m-resp\">I. Dignidad</mark> (arts. 1-5): dignidad, vida, integridad, tortura, esclavitud</div><div class=\"vis-rama\">II. Libertades (arts. 6-19)</div><div class=\"vis-rama\">III. Igualdad (arts. 20-26)</div><div class=\"vis-rama\">IV. Solidaridad (arts. 27-38)</div><div class=\"vis-rama\">V. Ciudadanía (arts. 39-46)</div><div class=\"vis-rama\">VI. Justicia (arts. 47-50)</div><div class=\"vis-rama\">VII. Disposiciones generales: interpretación y aplicación (arts. 51-54)</div></div></div></div>"}],"k-1":[{"t":"Título I · Dignidad (arts. 1-5)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Título I · Dignidad (arts. 1-5)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-destacable\">Dignidad</mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\">Art. 1 · <mark class=\"m-destacable\">dignidad humana</mark> inviolable: <mark class=\"m-resp\">respetada y protegida</mark></div><div class=\"vis-rama\">Art. 2 · <mark class=\"m-resp\">derecho a la vida</mark> · nadie <mark class=\"m-resp\">condenado a la pena de muerte ni ejecutado</mark></div><div class=\"vis-rama\">Art. 3 · integridad física y psíquica · <mark class=\"m-resp\">prohibición de las prácticas eugenésicas</mark>, de lucro con el cuerpo y de clonación reproductora</div><div class=\"vis-rama\">Art. 4 · tortura: penas o tratos <mark class=\"m-resp\">inhumanos o degradantes</mark></div><div class=\"vis-rama\">Art. 5 · esclavitud, trabajo forzado · <mark class=\"m-resp\">trata de seres humanos</mark></div></div></div></div>"}],"k-43":[{"t":"Título V · Ciudadanía (arts. 39-46)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Título V · Ciudadanía (arts. 39-46)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-destacable\">Ciudadanía</mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\">Art. 39 · sufragio activo y pasivo · diputados elegidos por <mark class=\"m-resp\">sufragio universal libre, directo y secreto</mark></div><div class=\"vis-rama\">Art. 41 · buena administración · respuesta <mark class=\"m-resp\">en esa misma lengua</mark></div><div class=\"vis-rama\">Art. 42 · acceso a <mark class=\"m-resp\">documentos de las instituciones, órganos y organismos de la Unión, cualquiera que sea su soporte</mark></div><div class=\"vis-rama\">Art. 43 · <mark class=\"m-autoridad\">Defensor</mark> del Pueblo Europeo: <mark class=\"m-resp\">mala administración</mark>, <mark class=\"m-resp\">con exclusión del Tribunal de Justicia en el ejercicio de sus funciones jurisdiccionales</mark></div><div class=\"vis-rama\">Art. 44 · petición ante el <mark class=\"m-resp\">Parlamento Europeo</mark></div><div class=\"vis-rama\">Art. 46 · protección diplomática y consular en tercer país <mark class=\"m-resp\">en el que no esté representado el Estado miembro del que sea nacional</mark></div></div></div></div>"}],"k-51":[{"t":"Ámbito y alcance de la Carta (arts. 51 y 52)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⇄</i>Ámbito y alcance de la Carta (arts. 51 y 52)</div><div class=\"vis-comp\" style=\"--n:2\"><div class=\"vis-col\"><h5>Art. 51 · Ámbito</h5><ul><li>Instituciones, <mark class=\"m-autoridad\">órganos</mark> y organismos de la Unión (subsidiariedad)</li><li><mark class=\"m-autoridad\">Estados</mark> miembros <u class=\"m-clave\">únicamente</u> cuando apliquen el Derecho de la Unión</li><li><u class=\"m-clave\">No</u> amplía el ámbito del Derecho de la Unión</li><li><u class=\"m-clave\">Ni</u> crea competencias o misiones nuevas</li><li><u class=\"m-clave\">Ni</u> modifica las competencias de los Tratados</li></ul></div><div class=\"vis-col\"><h5>Art. 52 · Alcance</h5><ul><li>Limitaciones: establecidas por ley y respetando el contenido esencial</li><li>Derechos correspondientes al CEDH: <mark class=\"m-resp\">mismo sentido y alcance</mark></li><li><mark class=\"m-resp\">El Derecho de la Unión puede conceder una protección más extensa</mark></li><li>Principios: se aplican mediante actos legislativos y ejecutivos</li><li><mark class=\"m-resp\">Solo podrán alegarse ante un órgano jurisdiccional para interpretar y controlar la legalidad de dichos actos</mark></li></ul></div></div></div>"}],"n-3":[{"t":"Miembros del Consejo de Europa (arts. 3-6)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Miembros del Consejo de Europa (arts. 3-6)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-destacable\">Ser miembro</mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\">Art. 3 · reconoce el principio del <mark class=\"m-resp\">imperio del Derecho</mark> y de los derechos humanos</div><div class=\"vis-rama\">Art. 4 · <mark class=\"m-autoridad\">Estado</mark> europeo invitado por el <mark class=\"m-autoridad\">Comité de Ministros:</mark> es Miembro <mark class=\"m-resp\">tan pronto como se remita al Secretario General un instrumento de adhesión</mark></div><div class=\"vis-rama\">Art. 5 · Miembro asociado: solo representado en la <mark class=\"m-resp\">Asamblea Consultiva</mark></div><div class=\"vis-rama\">Art. 6 · el <mark class=\"m-autoridad\">Comité</mark> determina su nº de representantes en la <mark class=\"m-autoridad\">Asamblea</mark> y su contribución</div></div></div></div>"}],"n-7":[{"t":"Retirada y suspensión (arts. 7, 8 y 9)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>➜</i>Retirada y suspensión (arts. 7, 8 y 9)</div><div class=\"vis-flujo\"><div class=\"vis-paso \"><span class=\"et\">7</span>Retirada: notificar la decisión al <mark class=\"m-autoridad\">Secretario</mark> General · efecto <mark class=\"m-resp\">al concluir el año financiero en curso, si tuvo lugar en los primeros nueve meses; al finalizar el año siguiente, si fue en los tres últimos meses</mark></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">8</span>Infracción grave del art. 3: el <mark class=\"m-autoridad\">Comité</mark> <mark class=\"m-resp\">deja en suspenso el derecho de representación e invita a retirarse</mark>; si no atiende, cesa como Miembro</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">9</span>Impago de obligaciones financieras: <mark class=\"m-resp\">suspender su derecho de representación en el Comité y en la Asamblea Consultiva mientras no pague</mark></div></div></div>"}],"n-10":[{"t":"Órganos del Consejo de Europa (arts. 10-12)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Órganos del Consejo de Europa (arts. 10-12)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-autoridad\">Consejo</mark> <mark class=\"m-destacable\">de Europa</mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\"><b><mark class=\"m-autoridad\">Órganos</mark></b> (art. 10): i) <mark class=\"m-resp\">El Comité de Ministros</mark> ii) <mark class=\"m-resp\">La Asamblea Consultiva</mark></div><div class=\"vis-rama\">Ambos <mark class=\"m-accion\">serán</mark> asistidos por la <mark class=\"m-autoridad\">Secretaría del Consejo</mark> de Europa</div><div class=\"vis-rama\"><b>Sede</b> (art. 11): <mark class=\"m-resp\">Estrasburgo</mark></div><div class=\"vis-rama\"><b>Idiomas oficiales</b> (art. 12): <mark class=\"m-resp\">el francés y el inglés</mark></div></div></div></div>"}],"n-13":[{"t":"El Comité de Ministros (arts. 13-15)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>El Comité de Ministros (arts. 13-15)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-autoridad\">Comité</mark> <mark class=\"m-destacable\">de</mark> <mark class=\"m-autoridad\">Ministros</mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\"><mark class=\"m-autoridad\">Órgano</mark> competente que actúa en nombre del <mark class=\"m-autoridad\">Consejo</mark> de Europa</div><div class=\"vis-rama\">Cada Miembro: un representante y un voto · <mark class=\"m-resp\">los Ministros de Asuntos Exteriores</mark></div><div class=\"vis-rama\">Suplente (en la medida de lo posible, miembro del <mark class=\"m-autoridad\">Gobierno)</mark></div><div class=\"vis-rama\">Examina medidas por recomendación de la <mark class=\"m-autoridad\">Asamblea</mark> o por iniciativa propia · conclusiones: recomendaciones a los Gobiernos</div></div></div></div>"}],"n-16":[{"t":"Funciones internas del Comité (arts. 16-18)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Funciones internas del Comité (arts. 16-18)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-autoridad\">Comité</mark> <mark class=\"m-destacable\">de</mark> <mark class=\"m-autoridad\">Ministros</mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\">Art. 16 · resuelve con carácter obligatorio la organización y régimen interior; adopta los reglamentos financieros y administrativos</div><div class=\"vis-rama\">Art. 17 · puede constituir Comités o Comisiones de carácter consultivo o técnico</div><div class=\"vis-rama\">Art. 18 · su Reglamento interno determina:<div class=\"vis-sub\"><span>i) <mark class=\"m-resp\">el quórum</mark></span><span>ii) designación del <mark class=\"m-autoridad\">Presidente</mark> y duración</span><span>iii) procedimiento para temas y propuestas</span><span>iv) designación de suplentes</span></div></div></div></div></div>"}],"e-20":[{"t":"Mayorías del Comité de Ministros (art. 20)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Mayorías del Comité de Ministros (art. 20)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-destacable\">Mayorías</mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\">a) <b>Unanimidad</b> de los votos emitidos y mayoría de los representantes: cuestiones importantes<div class=\"vis-sub\"><span>recomendaciones (15 b)</span><span>informes a la <mark class=\"m-autoridad\">Asamblea</mark> (19)</span><span>reuniones y publicidad (21 a y b)</span><span>sede de la <mark class=\"m-autoridad\">Asamblea</mark> (33)</span><span>enmiendas a los arts. 1 d), 7, 15, 20 y 22</span></div></div><div class=\"vis-rama\">b) <mark class=\"m-resp\">Mayoría simple</mark> de los representantes con derecho a formar parte del <mark class=\"m-autoridad\">Comité:</mark> reglamento interno y regímenes financiero y administrativo</div><div class=\"vis-rama\">c) <mark class=\"m-resp\">Mayoría de los dos tercios de los representantes con derecho a participar</mark>: invitar Miembros y Miembros asociados (arts. 4 y 5)</div><div class=\"vis-rama\">d) Todas las demás: dos tercios de los votos emitidos y mayoría de los representantes (incluso el presupuesto)</div></div></div></div>"},{"t":"Cosa juzgada (art. 20)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Cosa juzgada (art. 20)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-destacable\">Non bis in idem</mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\">Nadie <mark class=\"m-accion\">será</mark> procesado por la <mark class=\"m-autoridad\">Corte</mark> por crímenes por los que ya hubiere sido condenado o absuelto por la <mark class=\"m-autoridad\">Corte</mark></div><div class=\"vis-rama\">Nadie <mark class=\"m-accion\">será</mark> procesado por otro <mark class=\"m-autoridad\">tribunal</mark> por crímenes del art. 5 por los que la <mark class=\"m-autoridad\">Corte</mark> ya le condenó o absolvió</div><div class=\"vis-rama\">La <mark class=\"m-autoridad\">Corte</mark> <mark class=\"m-accion\">no procesará</mark> a quien ya fue procesado por otro <mark class=\"m-autoridad\">tribunal,</mark> <u class=\"m-clave\">a menos que</u> el proceso:<div class=\"vis-sub\"><span>a) <mark class=\"m-resp\">Obedeciera al propósito de sustraer al acusado de su responsabilidad penal</mark></span><span>b) <mark class=\"m-resp\">No hubiere sido instruido en forma independiente o imparcial</mark></span></div></div></div></div></div>"}],"e-21":[{"t":"Reuniones del Comité (art. 21)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⇄</i>Reuniones del Comité (art. 21)</div><div class=\"vis-comp\" style=\"--n:2\"><div class=\"vis-col\"><h5>Regla general</h5><ul><li><mark class=\"m-resp\">A puerta cerrada</mark></li><li><mark class=\"m-resp\">En la sede del Consejo</mark></li><li>Salvo acuerdo en contrario del <mark class=\"m-autoridad\">Comité</mark></li></ul></div><div class=\"vis-col\"><h5>Obligatoriamente</h5><ul><li>Antes de la apertura y al comienzo de las reuniones de la <mark class=\"m-autoridad\">Asamblea</mark></li><li>Además, cuantas veces lo estime conveniente</li><li>Publicidad de las deliberaciones: lo decide el <mark class=\"m-autoridad\">Comité</mark> (por unanimidad y mayoría de representantes)</li></ul></div></div></div>"},{"t":"Derecho aplicable por la Corte (art. 21)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>➜</i>Derecho aplicable por la Corte (art. 21)</div><div class=\"vis-flujo\"><div class=\"vis-paso \"><span class=\"et\">1.º</span><u class=\"m-clave\">EN PRIMER LUGAR</u>: <mark class=\"m-resp\">el presente Estatuto, los Elementos de los crímenes y sus Reglas de Procedimiento y Prueba</mark></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">2.º</span><u class=\"m-clave\">EN SEGUNDO LUGAR</u>: tratados aplicables, principios y normas del derecho internacional</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">3.º</span><u class=\"m-clave\">EN SU DEFECTO</u>: principios generales del derecho que derive la <mark class=\"m-autoridad\">Corte</mark> del derecho interno de los sistemas jurídicos del mundo</div></div></div>"}],"n-29":[{"t":"Asamblea Consultiva frente al Comité de Ministros","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⇄</i>Asamblea Consultiva frente al Comité de Ministros</div><div class=\"vis-comp med\" style=\"--n:2\"><div class=\"vis-col\"><h5><mark class=\"m-autoridad\">Comité de Ministros</mark></h5><ul><li><mark class=\"m-autoridad\">Órgano</mark> competente que actúa en nombre del <mark class=\"m-autoridad\">Consejo</mark></li><li>Un representante y un voto por Miembro: <mark class=\"m-autoridad\">Ministros</mark> de Asuntos Exteriores</li><li>Reuniones a puerta cerrada y en la sede</li><li>Decide por unanimidad, mayoría simple o dos tercios según la materia</li></ul></div><div class=\"vis-mid\">⇄</div><div class=\"vis-col\"><h5><mark class=\"m-autoridad\">Asamblea</mark> Consultiva</h5><ul><li><mark class=\"m-autoridad\">Órgano</mark> <mark class=\"m-destacable\">deliberante</mark>: transmite conclusiones como <mark class=\"m-resp\">recomendaciones</mark></li><li>Representantes elegidos por su <mark class=\"m-autoridad\">Parlamento;</mark> <mark class=\"m-resp\">nacionalidad del Miembro y no a la vez miembro del Comité</mark></li><li>Resoluciones por <mark class=\"m-resp\">mayoría de los dos tercios de los votos emitidos</mark></li><li>Sesión ordinaria anual: <mark class=\"m-resp\">no excederá de un mes</mark></li><li>Deliberaciones <mark class=\"m-resp\">públicas, a menos que ella misma acuerde lo contrario</mark></li><li><mark class=\"m-autoridad\">Presidente:</mark> <mark class=\"m-resp\">dirige las deliberaciones, pero no participa en los debates ni en la votación</mark></li><li>España: <mark class=\"m-resp\">12</mark> representantes</li></ul></div></div></div>"}],"n-36":[{"t":"La Secretaría (arts. 36-37)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>La Secretaría (arts. 36-37)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-autoridad\">Secretaría</mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\">Compuesta por: <mark class=\"m-autoridad\">Secretario</mark> General, <mark class=\"m-autoridad\">Secretario</mark> General Adjunto y personal necesario</div><div class=\"vis-rama\">SG y SG Adjunto: <mark class=\"m-resp\">nombrados por la Asamblea Consultiva por recomendación del Comité de Ministros</mark></div><div class=\"vis-rama\">Los demás miembros: nombrados por el <mark class=\"m-autoridad\">Secretario</mark> General</div><div class=\"vis-rama\">Instalada en la sede · el <mark class=\"m-autoridad\">Secretario</mark> General responde ante el <mark class=\"m-autoridad\">Comité de Ministros</mark></div></div></div></div>"}],"n-41":[{"t":"Cifras del Estatuto del Consejo de Europa","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⏱</i>Cifras del Estatuto del Consejo de Europa</div><div class=\"vis-plazos\"><div class=\"vis-plazo\"><span class=\"n\">5-5-1949</span><mark class=\"m-resp\">Londres, a los cinco días del mes de mayo de 1949</mark></div><div class=\"vis-plazo\"><span class=\"n\">24-11-1977</span>España: Instrumento de Adhesión · miembro de pleno derecho</div><div class=\"vis-plazo\"><span class=\"n\">7</span>Instrumentos de ratificación para entrar en vigor (<mark class=\"m-resp\">siete</mark>)</div><div class=\"vis-plazo\"><span class=\"n\">2/3</span>Protocolos de enmienda: firmados y ratificados por las dos terceras partes de los Miembros</div><div class=\"vis-plazo\"><span class=\"n\">9 meses</span>Retirada: primeros nueve meses → efecto al concluir el año financiero en curso</div><div class=\"vis-plazo\"><span class=\"n\">6 meses</span>Plazo máximo para abonar la contribución (art. 39)</div><div class=\"vis-plazo\"><span class=\"n\">1 mes</span>Duración máxima de las sesiones ordinarias de la <mark class=\"m-autoridad\">Asamblea</mark> (art. 32)</div></div></div>"}],"h-2":[{"t":"Uso de la fuerza: la muerte no infringe el art. 2 (CEDH)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Uso de la fuerza: la muerte no infringe el art. 2 (CEDH)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-destacable\">Recurso a la fuerza absolutamente necesario</mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\">a) <mark class=\"m-resp\">En defensa de una persona contra una agresión ilegítima</mark></div><div class=\"vis-rama\">b) <mark class=\"m-resp\">Para detener a una persona conforme a derecho o para impedir la evasión de un preso o detenido legalmente</mark></div><div class=\"vis-rama\">c) <mark class=\"m-resp\">Para reprimir, de acuerdo con la ley, una revuelta o insurrección</mark></div></div></div></div>"}],"h-6":[{"t":"Derogación en estado de excepción (art. 15 CEDH)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Derogación en estado de excepción (art. 15 CEDH)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-destacable\">Art. 15</mark>: guerra o peligro público</div><div class=\"vis-ramas\"><div class=\"vis-rama\"><mark class=\"m-accion\">Podrán derogarse</mark> obligaciones en la medida estricta que exija la situación</div><div class=\"vis-rama\"><u class=\"m-clave\">Nunca</u> derogables: <mark class=\"m-resp\">artículo 2</mark> (salvo actos lícitos de guerra)</div><div class=\"vis-rama\"><u class=\"m-clave\">Nunca</u> derogables: <mark class=\"m-resp\">artículos 3, 4 (párrafo 1) y 7</mark> (tortura, esclavitud o servidumbre, legalidad)</div><div class=\"vis-rama\">Art. 16: restricciones a la actividad política de los extranjeros pese a los <mark class=\"m-resp\">artículos 10, 11 y 14</mark></div><div class=\"vis-rama\">Informar al <mark class=\"m-autoridad\">Secretario</mark> general del <mark class=\"m-autoridad\">Consejo</mark> de Europa</div></div></div></div>"}],"h-19":[{"t":"Los jueces del Tribunal (arts. 19-23)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Los jueces del Tribunal (arts. 19-23)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-autoridad\">Tribunal</mark> <mark class=\"m-destacable\">Europeo de Derechos Humanos</mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\">Art. 19 · <mark class=\"m-accion\">funcionará</mark> <mark class=\"m-resp\">de manera permanente</mark></div><div class=\"vis-rama\">Art. 20 · número de <mark class=\"m-autoridad\">jueces</mark> <mark class=\"m-resp\">igual al de las Altas Partes Contratantes</mark></div><div class=\"vis-rama\">Art. 21 · candidatos <mark class=\"m-resp\">menores de 65 años</mark> · actúan a título individual</div><div class=\"vis-rama\">Art. 22 · elegidos <mark class=\"m-resp\">por la Asamblea Parlamentaria</mark>, <mark class=\"m-resp\">por mayoría absoluta de votos</mark>, <mark class=\"m-resp\">de una lista de tres candidatos</mark></div><div class=\"vis-rama\">Art. 23 · mandato de <mark class=\"m-resp\">nueve años</mark>, <mark class=\"m-resp\">no reelegibles</mark> · relevo solo si <mark class=\"m-resp\">los demás jueces deciden, por mayoría de dos tercios</mark></div></div></div></div>"}],"h-25":[{"t":"Formaciones del Tribunal (arts. 25 y 26)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Formaciones del Tribunal (arts. 25 y 26)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-autoridad\">Tribunal</mark> (Pleno)</div><div class=\"vis-ramas\"><div class=\"vis-rama\">Pleno (art. 25): elige <mark class=\"m-resp\">por un período de tres años</mark> al <mark class=\"m-autoridad\">Presidente</mark> y a uno o dos Vicepresidentes (<mark class=\"m-resp\">reelegibles</mark>); constituye las <mark class=\"m-autoridad\">Salas</mark></div><div class=\"vis-rama\"><mark class=\"m-autoridad\">Juez</mark> único (art. 27)</div><div class=\"vis-rama\"><mark class=\"m-resp\">Comités compuestos por tres jueces</mark> (art. 28)</div><div class=\"vis-rama\"><mark class=\"m-autoridad\">Salas</mark> de siete <mark class=\"m-autoridad\">jueces</mark> · <mark class=\"m-resp\">el Comité de Ministros podrá, por decisión unánime, reducir a cinco</mark> el nº de <mark class=\"m-autoridad\">jueces</mark> de las <mark class=\"m-autoridad\">Salas</mark></div><div class=\"vis-rama\"><mark class=\"m-resp\">Gran Sala de diecisiete jueces</mark> · en la remisión: del grupo de la <mark class=\"m-autoridad\">Sala</mark> solo <mark class=\"m-resp\">el Presidente de la Sala y el Juez de la Alta Parte interesada</mark></div><div class=\"vis-rama\"><mark class=\"m-autoridad\">Juez</mark> único: <mark class=\"m-resp\">ningún juez podrá examinar una solicitud contra la Alta Parte en cuya representación fue elegido</mark></div></div></div></div>"}],"h-27":[{"t":"Camino de una demanda individual (arts. 27, 28, 35, 43-46)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>➜</i>Camino de una demanda individual (arts. 27, 28, 35, 43-46)</div><div class=\"vis-flujo\"><div class=\"vis-paso \"><span class=\"et\">1</span>Agotar las vías internas y presentar la demanda <mark class=\"m-resp\">en el plazo de cuatro meses a partir de la fecha de la resolución interna definitiva</mark> (art. 35)</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">2</span><mark class=\"m-autoridad\">Juez</mark> <mark class=\"m-destacable\">único</mark>: puede declarar inadmisible o eliminar del registro · su resolución <mark class=\"m-resp\">será definitiva</mark> (art. 27)</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">3</span><mark class=\"m-autoridad\">Comité</mark> <mark class=\"m-destacable\">de 3</mark> <mark class=\"m-autoridad\">jueces</mark>, <mark class=\"m-resp\">por unanimidad</mark>: inadmisible, o <mark class=\"m-resp\">admisible y sentencia sobre el fondo si ya hay jurisprudencia bien establecida</mark> (art. 28)</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">4</span><mark class=\"m-autoridad\">Sala</mark> <mark class=\"m-destacable\">de 7</mark> <mark class=\"m-autoridad\">jueces</mark>: examen y sentencia</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">5</span>Remisión excepcional a la Gran <mark class=\"m-autoridad\">Sala:</mark> <mark class=\"m-resp\">en el plazo de tres meses a partir de la fecha de la sentencia de una Sala</mark> · acepta <mark class=\"m-resp\">un colegio de cinco Jueces de la Gran Sala</mark> (art. 43)</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">6</span>Sentencia definitiva (art. 44) · transmitida al <mark class=\"m-resp\">Comité de Ministros, que velará por su ejecución</mark> (art. 46)</div></div></div>"}],"h-35":[{"t":"Inadmisibilidad de demandas individuales (art. 35)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Inadmisibilidad de demandas individuales (art. 35)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-destacable\">El</mark> <mark class=\"m-autoridad\">Tribunal</mark> <mark class=\"m-destacable\">no admitirá…</mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\">a) Demanda anónima</div><div class=\"vis-rama\">b) Esencialmente la misma que una ya examinada por el <mark class=\"m-autoridad\">Tribunal</mark> o sometida a otra instancia internacional, sin hechos nuevos</div><div class=\"vis-rama\">c) Incompatible con el Convenio, manifiestamente mal fundada o abusiva</div><div class=\"vis-rama\">d) El demandante no ha sufrido un perjuicio importante, <u class=\"m-clave\">a menos que</u> <mark class=\"m-resp\">el respeto de los derechos humanos garantizados por el Convenio y sus Protocolos exija un examen del fondo de la demanda</mark></div><div class=\"vis-rama\">Art. 36 · tercero que puede presentar observaciones: <mark class=\"m-resp\">el Comisario de Derechos Humanos del Consejo de Europa</mark></div></div></div></div>"}],"h-43":[{"t":"Remisión y firmeza de las sentencias (arts. 43-46)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⇄</i>Remisión y firmeza de las sentencias (arts. 43-46)</div><div class=\"vis-comp\" style=\"--n:2\"><div class=\"vis-col\"><h5>Sentencia de una <mark class=\"m-autoridad\">Sala</mark></h5><ul><li>Definitiva si: las partes <mark class=\"m-accion\">no solicitarán</mark> la remisión, o <mark class=\"m-plazo\">tres meses</mark> sin solicitarla, o el colegio rechaza la remisión</li><li>Remisión en <mark class=\"m-resp\">tres meses</mark>; acepta un colegio de <mark class=\"m-resp\">5 jueces</mark></li></ul></div><div class=\"vis-col\"><h5>Sentencia de la Gran <mark class=\"m-autoridad\">Sala</mark></h5><ul><li>Siempre definitiva (art. 44.1)</li><li><mark class=\"m-resp\">Opinión por separado</mark>: cualquier <mark class=\"m-autoridad\">Juez</mark> tiene derecho a unir su opinión (art. 45)</li><li>Ejecución: <mark class=\"m-resp\">Comité de Ministros</mark> (art. 46)</li><li>Remitir al <mark class=\"m-autoridad\">Tribunal</mark> un problema de interpretación: mayoría de <mark class=\"m-plazo\">dos tercios</mark> de los representantes del <mark class=\"m-autoridad\">Comité</mark></li></ul></div></div></div>"}],"h-47":[{"t":"Opiniones consultivas y gastos (arts. 47-50)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Opiniones consultivas y gastos (arts. 47-50)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-destacable\">Opinión consultiva</mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\">Pide el <mark class=\"m-autoridad\">Comité de Ministros</mark> · el <mark class=\"m-autoridad\">Tribunal</mark> emite sobre cuestiones jurídicas de interpretación del Convenio y sus Protocolos</div><div class=\"vis-rama\"><u class=\"m-clave\">No</u> sobre el contenido o extensión de los derechos del Título I</div><div class=\"vis-rama\">La decisión de pedirla: <mark class=\"m-resp\">voto mayoritario de los representantes del Comité</mark></div><div class=\"vis-rama\">Gastos de funcionamiento del <mark class=\"m-autoridad\">Tribunal:</mark> <mark class=\"m-resp\">Consejo de Europa</mark></div></div></div></div>"}],"h-56":[{"t":"Plazos y cifras del Convenio","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⏱</i>Plazos y cifras del Convenio</div><div class=\"vis-plazos\"><div class=\"vis-plazo\"><span class=\"n\">4 meses</span>Presentar la demanda tras la resolución interna definitiva (art. 35)</div><div class=\"vis-plazo\"><span class=\"n\">3 meses</span>Solicitar la remisión a la Gran <mark class=\"m-autoridad\">Sala</mark> (art. 43)</div><div class=\"vis-plazo\"><span class=\"n\">9 años</span>Mandato de los <mark class=\"m-autoridad\">jueces,</mark> no reelegibles (art. 23)</div><div class=\"vis-plazo\"><span class=\"n\">65 años</span>Edad máxima de los candidatos a <mark class=\"m-autoridad\">juez</mark> (art. 21)</div><div class=\"vis-plazo\"><span class=\"n\">3 años</span>Mandato del <mark class=\"m-autoridad\">Presidente</mark> y Vicepresidentes del <mark class=\"m-autoridad\">Tribunal</mark> (art. 25)</div><div class=\"vis-plazo\"><span class=\"n\">30 días</span>Aplicación territorial: desde el trigésimo día siguiente (art. 56)</div><div class=\"vis-plazo\"><span class=\"n\">5 años + 6 meses</span>Denuncia: tras cinco años de vigor para la Parte y preaviso de seis meses (art. 58)</div><div class=\"vis-plazo\"><span class=\"n\">10</span>Instrumentos de ratificación para la entrada en vigor del Convenio (art. 59)</div><div class=\"vis-plazo\"><span class=\"n\">3 / 7 / 17</span><mark class=\"m-autoridad\">Jueces de Comité, de Sala</mark> y de Gran <mark class=\"m-autoridad\">Sala</mark></div><div class=\"vis-plazo\"><span class=\"n\">4-11-1950</span>Hecho en <mark class=\"m-resp\">Roma</mark> el 4 de noviembre de 1950</div></div></div>"}],"h-13":[{"t":"Pena de muerte: Protocolos 6 y 13","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⇄</i>Pena de muerte: Protocolos 6 y 13</div><div class=\"vis-comp\" style=\"--n:2\"><div class=\"vis-col\"><h5>Protocolo n.º 6 (1983)</h5><ul><li>Abolida la pena de muerte</li><li>Excepción: <mark class=\"m-resp\">en tiempo de guerra o de peligro inminente de guerra</mark></li><li>Vigor: 5 <mark class=\"m-autoridad\">Estados</mark> miembros del <mark class=\"m-autoridad\">Consejo</mark> de Europa</li><li><mark class=\"m-autoridad\">Secretario</mark> General notifica firmas, depósitos, vigor y otros actos</li></ul></div><div class=\"vis-col\"><h5>Protocolo n.º 13 (Vilna, 2002)</h5><ul><li>Abolida en todas las circunstancias</li><li><u class=\"m-clave\">No</u> se autoriza excepción alguna (art. 15 del Convenio)</li><li><u class=\"m-clave\">No</u> se admite reserva alguna (art. 57)</li><li>Vigor: primer día del mes siguiente a <mark class=\"m-resp\">tres meses</mark> tras el consentimiento de 10 <mark class=\"m-autoridad\">Estados</mark></li></ul></div></div></div>"}],"e-5":[{"t":"Crímenes de la competencia de la Corte (arts. 5 y 6)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Crímenes de la competencia de la Corte (arts. 5 y 6)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-destacable\">Competencia de la</mark> <mark class=\"m-autoridad\">Corte</mark>: los crímenes más graves de trascendencia para la comunidad internacional</div><div class=\"vis-ramas\"><div class=\"vis-rama\">a) <mark class=\"m-resp\">El crimen de genocidio</mark> (art. 6): intención de destruir total o parcialmente a un <mark class=\"m-resp\">grupo nacional, étnico, racial o religioso</mark><div class=\"vis-sub\"><span>matanza de miembros</span><span>lesión grave a la integridad física o mental</span><span>sometimiento a condiciones de existencia de destrucción física</span><span>medidas para impedir nacimientos</span><span>traslado por la fuerza de niños</span></div></div><div class=\"vis-rama\">b) <mark class=\"m-resp\">Los crímenes de lesa humanidad</mark> (art. 7)</div><div class=\"vis-rama\">c) <mark class=\"m-resp\">Los crímenes de guerra</mark> (art. 8)</div><div class=\"vis-rama\">d) <mark class=\"m-resp\">El crimen de agresión</mark> (art. 8 bis)</div></div></div></div>"}],"e-7":[{"t":"Lesa humanidad frente a crímenes de guerra (arts. 7 y 8)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⇄</i>Lesa humanidad frente a crímenes de guerra (arts. 7 y 8)</div><div class=\"vis-comp\" style=\"--n:2\"><div class=\"vis-col\"><h5>Art. 7 · Lesa humanidad</h5><ul><li>Como parte de un <mark class=\"m-resp\">ataque generalizado o sistemático contra una población civil y con conocimiento de dicho ataque</mark></li><li>Asesinato, exterminio, esclavitud, deportación o traslado forzoso, tortura…</li><li>«Género»: <mark class=\"m-resp\">los dos sexos, masculino y femenino, en el contexto de la sociedad</mark></li></ul></div><div class=\"vis-col\"><h5>Art. 8 · Crímenes de guerra</h5><ul><li>Competencia, en particular, cuando se cometan como parte de un plan o política o en gran escala</li><li><mark class=\"m-resp\">Reclutar o alistar a niños menores de quince años en las fuerzas armadas nacionales</mark> o utilizarlos para participar activamente en las hostilidades</li></ul></div></div></div>"}],"e-8":[{"t":"Agresión y Elementos de los crímenes (arts. 8 bis y 9)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⇄</i>Agresión y Elementos de los crímenes (arts. 8 bis y 9)</div><div class=\"vis-comp\" style=\"--n:2\"><div class=\"vis-col\"><h5>Art. 8 bis · Agresión</h5><ul><li>Persona en condiciones de controlar o dirigir efectivamente la acción política o militar de un <mark class=\"m-autoridad\">Estado</mark></li><li>Acto de agresión: violación manifiesta de la Carta de las Naciones Unidas</li><li>Actos: <mark class=\"m-resp\">resolución 3314 (XXIX) de la Asamblea General, de 14 de diciembre de 1974</mark></li></ul></div><div class=\"vis-col\"><h5>Art. 9 · Elementos de los crímenes</h5><ul><li>Ayudan a la <mark class=\"m-autoridad\">Corte</mark> a interpretar los arts. 6, 7, 8 y 8 bis</li><li>Aprobados por <mark class=\"m-plazo\">dos tercios</mark> de la <mark class=\"m-autoridad\">Asamblea</mark> de los <mark class=\"m-autoridad\">Estados Partes</mark></li><li>Proponen enmiendas: <mark class=\"m-autoridad\">Estado</mark> Parte, el <mark class=\"m-autoridad\">fiscal</mark> y los <mark class=\"m-autoridad\">magistrados</mark> por <mark class=\"m-resp\">mayoría absoluta</mark></li><li>Aprobadas por <mark class=\"m-resp\">mayoría de dos tercios</mark></li></ul></div></div></div>"}],"e-11":[{"t":"Cuándo puede actuar la Corte (arts. 11-13)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Cuándo puede actuar la Corte (arts. 11-13)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-destacable\">Competencia de la</mark> <mark class=\"m-autoridad\">Corte</mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\">Art. 11 · temporal: <u class=\"m-clave\">únicamente</u> <mark class=\"m-resp\">crímenes cometidos después de la entrada en vigor del Estatuto</mark></div><div class=\"vis-rama\">Art. 12 · <mark class=\"m-autoridad\">Estados:</mark> territorio de la conducta (o <mark class=\"m-resp\">el Estado de matrícula del buque o la aeronave</mark>) o <mark class=\"m-autoridad\">Estado</mark> nacional del acusado</div><div class=\"vis-rama\">Art. 13 · quién activa la <mark class=\"m-autoridad\">Corte</mark> (tres vías):<div class=\"vis-sub\"><span>a) un <mark class=\"m-autoridad\">Estado</mark> Parte remite una situación al <mark class=\"m-autoridad\">fiscal</mark></span><span>b) el <mark class=\"m-resp\">Consejo de Seguridad, actuando con arreglo al Capítulo VII de la Carta de las Naciones Unidas</mark></span><span>c) el <mark class=\"m-autoridad\">fiscal</mark> inicia una investigación (art. 15)</span></div></div></div></div></div>"}],"e-15":[{"t":"Investigación de oficio (art. 15)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>➜</i>Investigación de oficio (art. 15)</div><div class=\"vis-flujo\"><div class=\"vis-paso \"><span class=\"et\">1</span>El <mark class=\"m-autoridad\">fiscal</mark> <mark class=\"m-resp\">inicia de oficio una investigación sobre la base de información acerca de un crimen de la competencia de la Corte</mark></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">2</span>Concluye que hay fundamento suficiente para investigar</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">3</span>Presenta petición de autorización a la <mark class=\"m-resp\">Sala de Cuestiones Preliminares</mark> · las víctimas <mark class=\"m-accion\">podrán presentar</mark> observaciones</div><div class=\"vis-flecha\">↓</div><div class=\"vis-bifurca\"><div class=\"vis-paso si\"><span class=\"et\">SÍ</span>La <mark class=\"m-autoridad\">Sala</mark> autoriza: se inicia la investigación</div><div class=\"vis-paso no\"><span class=\"et\">NO</span>La negativa no impide que el <mark class=\"m-autoridad\">fiscal</mark> presente otra petición basada en nuevos hechos o pruebas</div></div></div></div>"},{"t":"Crimen de agresión (art. 15 bis)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>➜</i>Crimen de agresión (art. 15 bis)</div><div class=\"vis-flujo\"><div class=\"vis-paso \"><span class=\"et\">1</span>Competencia: <mark class=\"m-resp\">un año después de la ratificación o aceptación de las enmiendas por treinta Estados Partes</mark></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">2</span><mark class=\"m-autoridad\">Estado</mark> no Parte: <mark class=\"m-resp\">la Corte no ejercerá su competencia cuando el crimen sea cometido por sus nacionales o en su territorio</mark></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">3</span>El <mark class=\"m-autoridad\">fiscal</mark> verifica en primer lugar si el <mark class=\"m-autoridad\">Consejo</mark> de Seguridad ha determinado un acto de agresión</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">4</span>Sin determinación en <mark class=\"m-resp\">seis meses</mark> desde la notificación: el <mark class=\"m-autoridad\">fiscal</mark> puede investigar, si la Sección de Cuestiones Preliminares lo autoriza y el <mark class=\"m-autoridad\">Consejo</mark> de Seguridad no decide lo contrario (art. 16)</div></div></div>"}],"e-16":[{"t":"Suspensión (art. 16) e inadmisibilidad (art. 17)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⇄</i>Suspensión (art. 16) e inadmisibilidad (art. 17)</div><div class=\"vis-comp\" style=\"--n:2\"><div class=\"vis-col\"><h5>Art. 16 · <mark class=\"m-autoridad\">Consejo</mark> de Seguridad</h5><ul><li>Resolución con arreglo al Capítulo VII</li><li>Pide que no se inicie o suspenda <mark class=\"m-resp\">por un plazo de doce meses</mark></li><li><mark class=\"m-resp\">Podrá ser renovada por el Consejo de Seguridad en las mismas condiciones</mark></li></ul></div><div class=\"vis-col\"><h5>Art. 17 · Inadmisibilidad</h5><ul><li>a) investigada o enjuiciada por un <mark class=\"m-autoridad\">Estado</mark> con jurisdicción, salvo que no esté dispuesto o no pueda</li><li>c) la persona ya fue enjuiciada por la conducta</li><li>d) el asunto no es de gravedad suficiente</li><li>Incapacidad: <mark class=\"m-resp\">no puede hacer comparecer al acusado, no dispone de las pruebas y los testimonios necesarios o no está por otras razones en condiciones de llevar a cabo el juicio</mark></li></ul></div></div></div>"}],"e-19":[{"t":"Impugnación de la competencia o la admisibilidad (art. 19)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Impugnación de la competencia o la admisibilidad (art. 19)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-destacable\">Impugnación</mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\">Quién (19.2):<div class=\"vis-sub\"><span>a) el acusado o la persona contra la que se dictó orden de detención o comparecencia</span><span>b) un <mark class=\"m-autoridad\">Estado</mark> con jurisdicción que investiga o enjuicia</span><span>c) un <mark class=\"m-autoridad\">Estado</mark> cuya aceptación se requiera (art. 12)</span></div></div><div class=\"vis-rama\">Cuándo: <u class=\"m-clave\">una sola vez</u>, antes del juicio o a su inicio · excepcional: <mark class=\"m-resp\">sólo podrán fundarse en el párrafo 1.c) del artículo 17</mark> (cosa juzgada)</div><div class=\"vis-rama\">Quién resuelve: antes de confirmar los cargos, <mark class=\"m-autoridad\">Sala</mark> de Cuestiones Preliminares; después, <mark class=\"m-autoridad\">Sala</mark> de Primera Instancia · recurso ante la <mark class=\"m-resp\">Sala de Apelaciones</mark></div><div class=\"vis-rama\">Efecto (19.7): si impugna un <mark class=\"m-autoridad\">Estado,</mark> <mark class=\"m-resp\">el fiscal suspenderá la investigación hasta que la Corte resuelva</mark></div><div class=\"vis-rama\">No afecta a la validez de actos anteriores</div></div></div></div>"}],"e-53":[{"t":"Decisión del fiscal de no investigar (art. 53)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>➜</i>Decisión del fiscal de no investigar (art. 53)</div><div class=\"vis-flujo\"><div class=\"vis-paso \"><span class=\"et\">1</span>El <mark class=\"m-autoridad\">fiscal</mark> inicia la investigación, a menos que determine que no hay fundamento razonable (causa inadmisible o no redundaría en interés de la justicia)</div><div class=\"vis-flecha\">↓</div><div class=\"vis-bifurca\"><div class=\"vis-paso \"><span class=\"et\">a</span>A petición del <mark class=\"m-autoridad\">Estado</mark> remitente o del <mark class=\"m-autoridad\">Consejo</mark> de Seguridad: la <mark class=\"m-autoridad\">Sala</mark> de Cuestiones Preliminares <mark class=\"m-accion\">podrá examinar</mark> la decisión y pedir que se reconsidere</div><div class=\"vis-paso \"><span class=\"et\">b</span><mark class=\"m-resp\">De oficio</mark>, <mark class=\"m-resp\">si la decisión se basare únicamente en el párrafo 1.c) o 2.c)</mark> (interés de la justicia)</div></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">=</span>La decisión del <mark class=\"m-autoridad\">fiscal</mark> <mark class=\"m-resp\">únicamente surtirá efecto si es confirmada por la Sala de Cuestiones Preliminares</mark></div></div></div>"}],"e-55":[{"t":"Derechos de la persona durante la investigación (art. 55)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Derechos de la persona durante la investigación (art. 55)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-destacable\">Investigación</mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\">a) <mark class=\"m-resp\">Nadie será obligado a declarar contra sí mismo ni a declararse culpable</mark></div><div class=\"vis-rama\">b) Nadie <mark class=\"m-accion\">será</mark> sometido a coacción, intimidación, amenaza ni torturas</div><div class=\"vis-rama\">c) Intérprete competente, sin cargo alguno</div><div class=\"vis-rama\">d) Nadie <mark class=\"m-accion\">será</mark> sometido a arresto o detención arbitrarios</div><div class=\"vis-rama\">Si hay motivos para creer que ha cometido un crimen: guardar silencio sin que se tenga en cuenta, y ser interrogada en presencia de su <mark class=\"m-autoridad\">abogado</mark></div><div class=\"vis-rama\">Art. 57: providencias de la <mark class=\"m-autoridad\">Sala</mark> de Cuestiones Preliminares (arts. 15, 18 o 19…): aprobadas por <mark class=\"m-resp\">la mayoría de los magistrados que la componen</mark></div></div></div></div>"}],"e-58":[{"t":"Orden de detención y detención en el Estado (arts. 58 y 59)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>➜</i>Orden de detención y detención en el Estado (arts. 58 y 59)</div><div class=\"vis-flujo\"><div class=\"vis-paso \"><span class=\"et\">1</span>El <mark class=\"m-autoridad\">fiscal</mark> solicita; la <mark class=\"m-autoridad\">Sala</mark> de Cuestiones Preliminares dicta orden de detención si hay motivo razonable para creer que se cometió un crimen y la detención parece necesaria (comparecencia, no obstruir, no reincidir)</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">2</span>La orden <mark class=\"m-resp\">seguirá en vigor mientras la Corte no disponga lo contrario</mark> · en su lugar, orden de comparecencia: notificación <mark class=\"m-resp\">personal</mark></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">3</span>El <mark class=\"m-autoridad\">Estado</mark> Parte toma inmediatamente las medidas para la detención; el detenido es llevado sin demora ante la <mark class=\"m-autoridad\">autoridad</mark> judicial competente</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">4</span>Libertad provisional: solo si hay circunstancias urgentes y excepcionales y salvaguardias · la <mark class=\"m-autoridad\">autoridad</mark> <mark class=\"m-resp\">no podrá examinar si la orden de detención fue dictada conforme a derecho</mark></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">5</span>La solicitud se notifica a la <mark class=\"m-resp\">Sala de Cuestiones Preliminares</mark>, que hace recomendaciones</div></div></div>"}],"e-60":[{"t":"Del primer momento ante la Corte al juicio (arts. 60 y 61)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>➜</i>Del primer momento ante la Corte al juicio (arts. 60 y 61)</div><div class=\"vis-flujo\"><div class=\"vis-paso \"><span class=\"et\">60</span>Entregado o comparecido el imputado: la <mark class=\"m-autoridad\">Sala</mark> de Cuestiones Preliminares comprueba que conoce los crímenes y sus derechos (incluida la libertad provisional)</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">60.5</span>Si es necesario, puede dictar <mark class=\"m-resp\">una orden de detención para hacer comparecer a una persona que haya sido puesta en libertad</mark></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">61</span><mark class=\"m-autoridad\">Audiencia</mark> de confirmación de cargos <mark class=\"m-resp\">en presencia del fiscal y del imputado, así como de su defensor</mark></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">61.2</span>Ausencia del acusado: <mark class=\"m-resp\">haya renunciado a su derecho a estar presente</mark> o <mark class=\"m-resp\">haya huido o no sea posible encontrarlo</mark></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">61.9</span>Confirmados los cargos, el <mark class=\"m-autoridad\">fiscal</mark> puede <mark class=\"m-resp\">modificar los cargos</mark> con autorización de la <mark class=\"m-autoridad\">Sala</mark></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">61.11</span>La <mark class=\"m-resp\">Presidencia</mark> constituye una <mark class=\"m-autoridad\">Sala</mark> de Primera Instancia para la siguiente fase</div></div></div>"}],"e-86":[{"t":"Cooperación de los Estados con la Corte (arts. 86 y 87)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Cooperación de los Estados con la Corte (arts. 86 y 87)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-destacable\">Cooperación</mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\">Art. 86 · los <mark class=\"m-autoridad\">Estados Partes</mark> <mark class=\"m-accion\">cooperarán</mark> <mark class=\"m-resp\">plenamente</mark></div><div class=\"vis-rama\">Art. 87 · solicitudes por vía diplomática o por el conducto designado por cada <mark class=\"m-autoridad\">Estado</mark> · también por conducto de <mark class=\"m-resp\">la Organización Internacional de Policía Criminal o de cualquier organización regional competente</mark></div><div class=\"vis-rama\">Idioma oficial del <mark class=\"m-autoridad\">Estado</mark> requerido (o traducción)</div><div class=\"vis-rama\">El <mark class=\"m-autoridad\">Estado</mark> requerido <mark class=\"m-resp\">preservará el carácter confidencial de toda solicitud de cooperación y de los documentos que las justifiquen</mark>, salvo lo necesario para tramitarla</div></div></div></div>"}],"e-89":[{"t":"Entrega y tránsito (art. 89)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Entrega y tránsito (art. 89)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-destacable\">Tránsito de personas entregadas a la</mark> <mark class=\"m-autoridad\">Corte</mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\">Cosa juzgada alegada ante <mark class=\"m-autoridad\">tribunal</mark> nacional: consultas inmediatas con la <mark class=\"m-autoridad\">Corte;</mark> si la causa es admisible, se cumple la entrega</div><div class=\"vis-rama\"><mark class=\"m-resp\">No se requerirá autorización cuando la persona sea transportada por vía aérea y no se prevea aterrizar en el territorio del Estado de tránsito</mark></div><div class=\"vis-rama\">Aterrizaje imprevisto: el <mark class=\"m-autoridad\">Estado</mark> de tránsito la detiene mientras recibe la solicitud · la detención <mark class=\"m-accion\">no podrá prolongarse</mark> más de <mark class=\"m-resp\">96 horas</mark></div></div></div></div>"}],"e-90":[{"t":"Solicitudes concurrentes: Corte y extradición (art. 90)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⇄</i>Solicitudes concurrentes: Corte y extradición (art. 90)</div><div class=\"vis-comp\" style=\"--n:2\"><div class=\"vis-col\"><h5><mark class=\"m-autoridad\">Estado</mark> requirente PARTE del Estatuto</h5><ul><li>Se notifica a la <mark class=\"m-autoridad\">Corte</mark> y al <mark class=\"m-autoridad\">Estado</mark> requirente</li><li>Prioridad a la solicitud de la <mark class=\"m-autoridad\">Corte</mark> si ha determinado que la causa es admisible</li></ul></div><div class=\"vis-col\"><h5><mark class=\"m-autoridad\">Estado</mark> requirente NO PARTE</h5><ul><li>Si <mark class=\"m-resp\">no está obligado por alguna norma internacional a conceder la extradición</mark>: <mark class=\"m-resp\">dará prioridad a la solicitud de entrega que le haya hecho la Corte si ésta ha determinado que la causa era admisible</mark></li><li>Si se deniega después la extradición: <mark class=\"m-resp\">el Estado requerido notificará su decisión a la Corte</mark></li></ul></div></div></div>"}],"e-91":[{"t":"Solicitud de detención y entrega (91) vs. detención provisional (92)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⇄</i>Solicitud de detención y entrega (91) vs. detención provisional (92)</div><div class=\"vis-comp\" style=\"--n:2\"><div class=\"vis-col\"><h5>Art. 91 · entrega</h5><ul><li>Por escrito; en urgencia, otro medio que deje constancia escrita, con confirmación</li><li>Contiene: información para identificar a la persona y su paradero; copia de la orden de detención; documentos necesarios</li><li>Los requisitos <u class=\"m-clave\">no</u> <mark class=\"m-accion\">podrán</mark> ser más onerosos que los de extradición</li></ul></div><div class=\"vis-col\"><h5>Art. 92 · detención provisional</h5><ul><li>En caso de urgencia, hasta que se presente la solicitud de entrega</li><li>Por cualquier medio que deje constancia escrita</li><li>Contiene: identificación y paradero · exposición concisa de los crímenes y hechos, <mark class=\"m-resp\">inclusive, de ser posible, la fecha y el lugar en que se cometieron</mark> · declaración de que existe orden de detención o decisión final condenatoria · declaración de que <mark class=\"m-accion\">se presentará</mark> solicitud de entrega</li></ul></div></div></div>"}],"e-93":[{"t":"Otras formas de cooperación (art. 93)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Otras formas de cooperación (art. 93)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-destacable\">Asistencia</mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\">Denegar solo en el caso del art. 72: <u class=\"m-clave\">únicamente</u> <mark class=\"m-resp\">si la solicitud se refiere a documentos o pruebas que afecten a su seguridad nacional</mark></div><div class=\"vis-rama\">Antes de denegar: considerar condiciones, fecha posterior u otra manera</div><div class=\"vis-rama\">Si no se da lugar: comunicar sin demora <mark class=\"m-resp\">los motivos a la Corte o al fiscal</mark></div><div class=\"vis-rama\">Traslado provisional de un detenido: consentimiento libre y con conocimiento + <mark class=\"m-autoridad\">Estado</mark> requerido lo acepta</div><div class=\"vis-rama\"><mark class=\"m-resp\">Cooperación activa</mark> (art. 93.10): la <mark class=\"m-autoridad\">Corte</mark> puede asistir a un <mark class=\"m-autoridad\">Estado</mark> Parte que investiga (art. 3 LO 18/2003)</div></div></div></div>"}],"e-100":[{"t":"Gastos, especialidad y términos (arts. 100-102)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⇄</i>Gastos, especialidad y términos (arts. 100-102)</div><div class=\"vis-comp\" style=\"--n:2\"><div class=\"vis-col\"><h5>Gastos (art. 100)</h5><ul><li>Ordinarios: <mark class=\"m-resp\">a cargo del Estado requerido</mark></li><li>A cargo de la <mark class=\"m-autoridad\">Corte:</mark> viaje y seguridad de testigos y peritos, traducción, dietas de <mark class=\"m-autoridad\">magistrados y fiscal,</mark> informes periciales, transporte del entregado…</li></ul></div><div class=\"vis-col\"><h5>Especialidad y términos</h5><ul><li>Art. 101: el entregado <mark class=\"m-resp\">no será procesado, castigado o detenido por una conducta anterior a su entrega</mark>, <u class=\"m-clave\">a menos que</u> sea la base del delito por el que fue entregado</li><li>Art. 102 · «entrega»: <mark class=\"m-resp\">de una persona por un Estado a la Corte</mark>; «extradición»: de un <mark class=\"m-autoridad\">Estado</mark> a otro <mark class=\"m-autoridad\">Estado</mark></li></ul></div></div></div>"}],"p-1":[{"t":"Privilegios de la Corte como institución (arts. 1-7)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Privilegios de la Corte como institución (arts. 1-7)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-destacable\">La</mark> <mark class=\"m-autoridad\">Corte</mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\">Art. 1 · «la <mark class=\"m-autoridad\">Presidencia»:</mark> <mark class=\"m-resp\">el Presidente y los Vicepresidentes primero y segundo</mark></div><div class=\"vis-rama\">Art. 2 · <mark class=\"m-resp\">personalidad jurídica internacional</mark> y capacidad jurídica necesaria</div><div class=\"vis-rama\">Art. 4 · locales <mark class=\"m-resp\">inviolables</mark></div><div class=\"vis-rama\">Art. 5 · pabellón y emblema <mark class=\"m-resp\">en sus locales y en los vehículos y otros medios de transporte que utilice con fines oficiales</mark></div><div class=\"vis-rama\">Art. 6 · inmunidad de jurisdicción; la renuncia <mark class=\"m-resp\">no es extensible a ninguna medida de ejecución</mark></div><div class=\"vis-rama\">Art. 7 · archivos <mark class=\"m-resp\">inviolables</mark></div></div></div></div>"}],"p-8":[{"t":"Impuestos y fondos (arts. 8 y 10)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Impuestos y fondos (arts. 8 y 10)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-destacable\">Hacienda de la</mark> <mark class=\"m-autoridad\">Corte</mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\">Art. 8 · exenta de impuestos directos; <u class=\"m-clave\">no</u> de los gravámenes que sean <mark class=\"m-resp\">la remuneración de servicios públicos prestados a una tarifa fija</mark></div><div class=\"vis-rama\">Exenta de derechos de aduana para uso oficial y publicaciones</div><div class=\"vis-rama\">Art. 10 · sin controles financieros ni moratorias · cambio <mark class=\"m-resp\">trato no menos favorable</mark> que a cualquier organización intergubernamental o misión diplomática</div></div></div></div>"}],"p-11":[{"t":"Comunicaciones, sede y representantes (arts. 11-13)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Comunicaciones, sede y representantes (arts. 11-13)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-autoridad\">Corte</mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\">Art. 11 · correspondencia <mark class=\"m-resp\">no sometida a censura alguna</mark> · comunicaciones oficiales inviolables</div><div class=\"vis-rama\">Art. 12 · sede: <mark class=\"m-resp\">La Haya (Países Bajos)</mark>; puede sesionar en otro lugar mediante acuerdo con el <mark class=\"m-autoridad\">Estado</mark></div><div class=\"vis-rama\">Art. 13 · representantes de <mark class=\"m-autoridad\">Estados Partes:</mark> inmunidad de arresto, de jurisdicción por actos oficiales, e inviolabilidad de documentos</div><div class=\"vis-rama\"><u class=\"m-clave\">No</u> es aplicable entre un representante y <mark class=\"m-resp\">las autoridades del Estado Parte del que sea nacional</mark></div></div></div></div>"}],"p-15":[{"t":"Quién goza de qué (arts. 15, 18, 20 y 22)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⇄</i>Quién goza de qué (arts. 15, 18, 20 y 22)</div><div class=\"vis-comp\" style=\"--n:3\"><div class=\"vis-col\"><h5><mark class=\"m-autoridad\">Magistrados, Fiscal, Fiscales</mark> Adjuntos y <mark class=\"m-autoridad\">Secretario</mark> (art. 15)</h5><ul><li>Privilegios de <mark class=\"m-resp\">los jefes de las misiones diplomáticas</mark></li><li>Sueldos exentos de impuestos</li><li>Los <mark class=\"m-autoridad\">Estados Partes</mark> <mark class=\"m-resp\">no estarán obligados a exonerar del impuesto a la renta</mark> las pensiones de ex <mark class=\"m-autoridad\">Magistrados</mark></li></ul></div><div class=\"vis-col\"><h5><mark class=\"m-autoridad\">Abogados</mark> (art. 18)</h5><ul><li>Inmunidad de arresto, de jurisdicción e inviolabilidad de documentos</li><li>Con certificado firmado por <mark class=\"m-resp\">el Secretario</mark></li></ul></div><div class=\"vis-col\"><h5>Víctimas (20) y otras personas (22)</h5><ul><li>Inmunidad de arresto, de incautación de equipaje y de jurisdicción; exención de restricciones de inmigración</li><li>Otras personas: <mark class=\"m-resp\">los apartados a) a d) del párrafo 1 del artículo 20</mark></li></ul></div></div></div>"}],"p-26":[{"t":"Quién puede renunciar a la inmunidad (art. 26)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Quién puede renunciar a la inmunidad (art. 26)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-destacable\">Renuncia</mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\"><mark class=\"m-autoridad\">Magistrado o Fiscal:</mark> <mark class=\"m-resp\">mayoría absoluta de los Magistrados</mark></div><div class=\"vis-rama\"><mark class=\"m-autoridad\">Secretario:</mark> <mark class=\"m-resp\">la Presidencia</mark></div><div class=\"vis-rama\"><mark class=\"m-autoridad\">Fiscales</mark> Adjuntos y personal de la <mark class=\"m-autoridad\">Fiscalía:</mark> <mark class=\"m-resp\">el Fiscal</mark></div><div class=\"vis-rama\"><mark class=\"m-autoridad\">Secretario</mark> Adjunto y personal de la <mark class=\"m-autoridad\">Secretaría: el Secretario</mark></div><div class=\"vis-rama\"><mark class=\"m-autoridad\">Abogados,</mark> testigos, víctimas y otras personas: la <mark class=\"m-autoridad\">Presidencia</mark></div><div class=\"vis-rama\">Peritos: el jefe del <mark class=\"m-autoridad\">órgano</mark> que los designó</div></div></div></div>"}],"p-27":[{"t":"Seguridad social, documentos de viaje y visados (arts. 27-30)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Seguridad social, documentos de viaje y visados (arts. 27-30)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-destacable\">Garantías</mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\">Art. 27 · exentos de <mark class=\"m-resp\">toda contribución obligatoria a los sistemas nacionales de seguridad social</mark></div><div class=\"vis-rama\">Art. 28 · el <mark class=\"m-autoridad\">Secretario</mark> comunica a los <mark class=\"m-autoridad\">Estados Partes</mark> <mark class=\"m-resp\">los nombres de los Magistrados, el Fiscal, los Fiscales Adjuntos, el Secretario, el Secretario Adjunto, el personal de la Fiscalía, el personal de la Secretaría y los abogados</mark></div><div class=\"vis-rama\">Art. 29 · documentos de viaje válidos: <mark class=\"m-resp\">los laissez passer de las Naciones Unidas o los documentos de viaje expedidos por la Corte</mark></div><div class=\"vis-rama\">Art. 30 · visados: <mark class=\"m-resp\">con la mayor rapidez posible y con carácter gratuito</mark></div></div></div></div>"}],"p-32":[{"t":"Arreglo de diferencias (art. 32)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>➜</i>Arreglo de diferencias (art. 32)</div><div class=\"vis-flujo\"><div class=\"vis-paso \"><span class=\"et\">1</span>Se resuelven <mark class=\"m-resp\">mediante consultas, negociación u otro medio convenido de arreglo</mark></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">2</span>Si no se resuelven en <mark class=\"m-plazo\">tres meses</mark> desde la solicitud por escrito: <mark class=\"m-resp\">tribunal arbitral</mark></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">3</span>Tres árbitros: uno por cada parte y el tercero <mark class=\"m-autoridad\">(presidente)</mark> elegido por los otros dos · si falta nombramiento <mark class=\"m-plazo\">dos meses</mark>: lo hace el <mark class=\"m-resp\">Presidente de la Corte Internacional de Justicia</mark></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">4</span>El laudo es definitivo y obligatorio para las partes</div></div></div>"}],"p-34":[{"t":"Firma y entrada en vigor del Acuerdo (arts. 34 y 35)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>➜</i>Firma y entrada en vigor del Acuerdo (arts. 34 y 35)</div><div class=\"vis-flujo\"><div class=\"vis-paso \"><span class=\"et\">9-9-2002</span>Abierto a la firma de todos los <mark class=\"m-autoridad\">Estados</mark> <mark class=\"m-resp\">desde el 10 de septiembre de 2002 hasta el 30 de junio de 2004</mark> en la Sede de la ONU en Nueva York</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">depósito</span>Ratificación, aceptación o aprobación en poder del <mark class=\"m-autoridad\">Secretario</mark> General de la ONU · abierto a la adhesión</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">vigor</span><mark class=\"m-resp\">Treinta días después de la fecha en que se deposite el décimo instrumento</mark></div></div></div>"}]};